'use strict';
const phaseOneTools={"title": "Thai learning and everyday translation", "intro": "Start with existing tools. Thai lessons and quick translation serve different needs.", "learn": "Learn Thai with LearnBig", "learnText": "Explore Thai lessons with Thai and Myanmar instruction on LearnBig. Videos use internet data.", "translate": "Open Google Translate", "translateText": "Open Google Translate for everyday words and phrases. Select your languages and use Listen when available.", "external": "These tools open outside Lift. Their own privacy terms apply. Lift sends none of your plan, questions or documents automatically.", "limits": "Machine translation can be wrong. Confirm important dates, amounts and instructions with a trusted person.", "status": "External resources; no Lift partnership or service availability is guaranteed.", "resourceLearn": "Thai language lessons", "resourceTranslate": "Everyday translation and listening", "visitLearn": "Visit LearnBig", "visitTranslate": "Visit Google Translate", "ydcText": "YDC remains our general learning platform. Life & Learning in Thailand is a planned optional collection. For Phase 1, use the external learning links here; our own Thai audio lessons are not available yet."};
function phaseOneLearningPanel(compact=false){const c=phaseOneTools;return `<section class="content-card language-tools">${compact?'':`<h2>${c.title}</h2><p>${c.intro}</p>`}<div class="language-tool-grid"><article class="language-tool"><span class="tool-symbol">${icon('learn')}</span><h3>${c.learn}</h3><p>${c.learnText}</p><a class="secondary" href="https://www.learnbig.net/thai-language-lessons/" target="_blank" rel="noopener noreferrer">${c.visitLearn} ${icon('arrow')}</a></article><article class="language-tool"><span class="tool-symbol">${icon('globe')}</span><h3>${c.translate}</h3><p>${c.translateText}</p><a class="secondary" href="https://translate.google.com/" target="_blank" rel="noopener noreferrer">${c.visitTranslate} ${icon('arrow')}</a></article></div><p class="dialog-note">${c.external}</p><p class="dialog-note">${c.limits}</p></section>`;}

const familyCopy={"title": "Learning for my family", "intro": "Prepare a conversation about a child's learning. You do not need to enter a child's name, documents, school or location.", "card": "A child's learning matters too. Prepare questions for a school, learning centre or trusted educator.", "choose": "What would help your family?", "start": "Find a learning pathway", "language": "Learn across languages", "routine": "Make time for learning", "device": "Learn with a shared phone", "cost": "Understand practical costs", "support": "Ask about additional support", "startQ": "Which learning options could fit the child's age and current learning level, and who can explain enrolment requirements?", "languageQ": "Which languages can the child use now, and what support is available for learning Thai while keeping their first language?", "routineQ": "What short learning activities can a caregiver and child try together, and what schedule could fit the family?", "deviceQ": "Can activities work without a phone, with printed materials, or offline on a shared phone?", "costQ": "What are the costs for materials, travel, uniforms or other items, and is any help available?", "supportQ": "What support is available if the child has difficulty seeing, hearing, moving, communicating or participating in learning?", "questions": "Questions to take with me", "toggle": "Mark a question when you feel ready to ask it. These marks do not show a child's learning progress or a school's response.", "privacy": "Your choices follow Lift's plan-saving setting. Saving is off by default. Anyone using a shared browser may see saved choices. Clearing your plan also clears these choices.", "download": "Review my questions", "exportTitle": "My family learning questions", "exportNote": "Prepared in Lift. These are questions, not admission advice or a confirmed service. Check the school's or learning centre's current arrangements directly.", "downloadFile": "Download my questions", "downloadNote": "Nothing is sent to a school or organisation. A downloaded copy remains in your files and can be read by others using the device.", "none": "Choose at least one topic to prepare your questions.", "pathways": "Understand the available pathways", "pathwaysText": "Schools and migrant learning centres may offer different learning pathways. The reports below explain the wider context; they are not local service directories or confirmation of a place for your child.", "unicef": "UNICEF: migrant learning centres", "unesco": "UNESCO: education for Myanmar migrant children in Thailand", "sources": "These original reports are in English. Source links were checked on 14 October 2026. Neither organisation is a Lift partner.", "ydc": "YDC: the next learning pathway", "ydcText": "YDC remains our general learning platform. Life & Learning in Thailand is a planned optional collection. For Phase 1, use the external learning links here; our own Thai audio lessons are not available yet.", "ydcResearch": "Tell us what your family needs through the optional adult research survey. Do not include children's names or private details.", "survey": "Share learning needs", "adult": "This page is for parents, caregivers and educators. It does not collect children's responses or connect children to strangers.", "noPromise": "Lift cannot confirm school admission, document requirements, accreditation or individual education rights. Ask the relevant school, learning centre or a trusted education adviser."};
function familyLabel(key){return familyCopy[key];}
function familyPage(){
 const family=LiftFamily.normalize(state.family);
 return `${heading('Your next step, together',familyLabel('title'),familyLabel('intro'))}<div class="page-grid"><div><a class="secondary" href="#language">${phaseOneTools.title} ${icon('globe')}</a><section class="content-card"><h2>${familyLabel('choose')}</h2><div class="family-topics">${LiftFamily.topics.map(key=>`<label class="family-choice"><input type="checkbox" data-family-topic="${key}" ${family.topics.includes(key)?'checked':''}><span>${familyLabel(key)}</span></label>`).join('')}</div></section><section class="content-card"><h2>${familyLabel('questions')}</h2><p>${familyLabel('toggle')}</p>${family.topics.length?`<ul class="family-questions">${family.topics.map(key=>`<li><label class="family-choice"><input type="checkbox" data-family-ready="${key}" ${family.ready.includes(key)?'checked':''}><span>${familyLabel(key+'Q')}</span></label></li>`).join('')}</ul><button class="primary" data-action="family-export">${familyLabel('download')}</button>`:`<p role="status">${familyLabel('none')}</p>`}<p class="dialog-note">${familyLabel('privacy')}</p></section><section class="content-card"><h2>${familyLabel('pathways')}</h2><p>${familyLabel('pathwaysText')}</p><ul><li><a href="https://www.unicef.org/thailand/reports/make-learning-count" target="_blank" rel="noopener noreferrer">${familyLabel('unicef')}</a></li><li><a href="https://core.unesco.org/en/project/567THA1001" target="_blank" rel="noopener noreferrer">${familyLabel('unesco')}</a></li></ul><p class="dialog-note">${familyLabel('sources')}</p><p>${familyLabel('noPromise')}</p></section></div><aside class="side-column"><section class="plan-card"><h2>${familyLabel('ydc')}</h2><p>${familyLabel('ydcText')}</p><p>${familyLabel('ydcResearch')}</p><a class="secondary" href="https://lift-next-step.vercel.app/survey">${familyLabel('survey')}</a></section><p class="private-note">${familyLabel('adult')}</p></aside></div>`;
}
const familyBaseHome=home;home=function(){const marker='<div class="section-heading"><div><h2>A path toward a steadier life</h2>',entry=`<section class="content-card family-entry"><h2>${familyLabel('title')}</h2><p>${familyLabel('card')}</p><a class="primary" href="#family">${familyLabel('title')}</a></section>`;return familyBaseHome().replace(marker,entry+marker);};
const familyBaseResources=resourcePage;resourcePage=function(){return familyBaseResources()+`<section class="content-card"><h2>${familyLabel('title')}</h2><p>${familyLabel('card')}</p><a class="secondary" href="#family">${familyLabel('title')}</a></section>`;};
function familyExportText(){const t=key=>LiftI18n.t(familyLabel(key));return [t('exportTitle'),...LiftFamily.questionKeys(state.family).map(t),t('exportNote')].join('\n\n');}
document.addEventListener('change',event=>{
 const input=event.target;if(input.matches('[data-family-topic]')){state.family=LiftFamily.toggleTopic(state.family,input.dataset.familyTopic,input.checked);persist();route();document.querySelector(`[data-family-topic="${input.dataset.familyTopic}"]`)?.focus();}
 if(input.matches('[data-family-ready]')){state.family=LiftFamily.toggleReady(state.family,input.dataset.familyReady,input.checked);persist();route();document.querySelector(`[data-family-ready="${input.dataset.familyReady}"]`)?.focus();}
});
document.addEventListener('click',event=>{
 const el=event.target.closest('[data-action]');if(!el)return;
 if(el.dataset.action==='family-export'&&LiftFamily.questionKeys(state.family).length)openDialog(`<h2 id="dialog-title">${familyLabel('exportTitle')}</h2><pre class="export-preview" data-user-content>${escapeText(familyExportText())}</pre><p>${familyLabel('downloadNote')}</p><div class="dialog-actions"><button class="primary" data-action="family-download">${familyLabel('downloadFile')}</button><button class="secondary" data-action="close">Cancel</button></div>`);
 if(el.dataset.action==='family-download'&&LiftFamily.questionKeys(state.family).length){const url=URL.createObjectURL(new Blob([familyExportText()],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='lift-learning-questions.txt';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);closeDialog();}
});
route();
